import { useAuth, useClerk } from '@clerk/expo';
import { GlassView, isGlassEffectAPIAvailable } from 'expo-glass-effect';
import { Redirect } from 'expo-router';
import { createElement, useEffect, useState } from 'react';
import { ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, Text, TextInput, useWindowDimensions, View } from 'react-native';
import Animated, { cancelAnimation, Easing, useAnimatedStyle, useSharedValue, withRepeat, withSequence, withTiming } from 'react-native-reanimated';
import { competitors, initialPriorities, initialSources, intelligence as fixture, opportunities, topics, type Intelligence, type Kind, type Opportunity } from '@/cedar-data';

type ScreenName = 'intelligence' | 'detail' | 'competitors' | 'competitor' | 'topics' | 'topic' | 'content' | 'deck' | 'context' | 'incident' | 'settings';
type Route = { page: ScreenName; id?: string };
type Draft = { title: string; note: string; body: string; sources: string[] };
const C = {
  abyss: '#08201A', bark: '#2A221C', copper: '#C77B45', copperLight: '#E9C88E', rust: '#A8502A',
  quartz: '#F7F2EA', sandstone: '#E8DDCB', mint: '#6EDDB0', oldGrowth: '#13382A',
  bg: '#F7F2EA', surface: '#FFFDF9', muted: '#F1E8DB', ink: '#2A221C', ink2: '#13382A',
  text: '#65594E', faint: '#907F6F', border: '#E0D3C1', threat: '#A8502A', threatBg: '#F5E2D6',
  flag: '#8B522C', flagBg: '#F1DEC7', op: '#13382A', opBg: '#DDF2E8',
};
const glyph = {
  drag: ['M9 5h.01M15 5h.01M9 12h.01M15 12h.01M9 19h.01M15 19h.01'],
  home: ['M3 10.5 12 3l9 7.5', 'M5 9.5v11h14v-11', 'M9.5 20.5v-6h5v6'],
  intelligence: ['M4 4v16h16', 'm7 15 4-5 3 3 4-8'], competitors: ['M4 15 6.5 5h4L12 15l1.5-10h4L20 15', 'M3 15a4 4 0 1 0 8 0 4 4 0 1 0-8 0ZM13 15a4 4 0 1 0 8 0 4 4 0 1 0-8 0ZM11 12h2'],
  topics: ['M9 3 7 21', 'm17 3-2 18', 'M4 9h16', 'M3 15h16'], content: ['M4 5h11v14H4z', 'm9 17 1-4L19.5 3.5a2.1 2.1 0 0 1 3 3L13 16l-4 1Z', 'm17.5 5.5 3 3'],
  context: ['M4 21V3h12v18M16 9h4v12M8 7h3M8 11h3M8 15h3M17 13h1M17 17h1'], settings: ['M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.38a2 2 0 0 0-.73-2.73l-.15-.09a2 2 0 0 1-1-1.74v-.51a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2Z', 'M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z'],
  bell: ['M18 10a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9', 'M10 22h4'], menu: ['M4 7h16', 'M4 12h16', 'M4 17h16'],
  cedar: ['m12 2 1.2 5.8L19 9l-5.8 1.2L12 16l-1.2-5.8L5 9l5.8-1.2L12 2Z', 'm19 15 .55 2.45L22 18l-2.45.55L19 21l-.55-2.45L16 18l2.45-.55L19 15Z'],
  close: ['M6 6l12 12', 'M18 6 6 18'], inbox: ['M4 5h16v14H4z', 'M4 14h5l2 2h2l2-2h5'], deck: ['M5 21V4', 'M5 5h13l-2 3 2 3H5', 'M9 5v6M13 5v6'], calendar: ['M5 4h14v16H5z', 'M8 2v4M16 2v4M5 9h14'], users: ['M16 20v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2', 'M10 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8', 'M16 4a4 4 0 0 1 0 8'],
} as const;
type GlyphName = keyof typeof glyph;
const nav = [['intelligence', 'Intelligence', 'intelligence'], ['competitors', 'Positioning', 'competitors'], ['content', 'Content Advisor', 'content'], ['deck', 'On Deck', 'deck'], ['context', 'Company Context', 'context']] as const;
const kindColor = (kind: Kind) => kind === 'threat' ? [C.threat, C.threatBg] : kind === 'flag' ? [C.flag, C.flagBg] : [C.op, C.opBg];
const getObject = (items: Intelligence[], id?: string) => items.find((item) => item.id === id);

export default function App() { return process.env.EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY ? <AuthenticatedApp /> : <CedarWorkspace />; }

function AuthenticatedApp() {
  const { isLoaded, isSignedIn } = useAuth();
  const { signOut } = useClerk();
  if (!isLoaded) return <View style={{ alignItems: 'center', backgroundColor: C.bg, flex: 1, justifyContent: 'center' }}><ActivityIndicator color={C.ink} size="large" /></View>;
  if (!isSignedIn) return <Redirect href="/sign-in" />;
  return <CedarWorkspace signOut={() => void signOut()} />;
}

function CedarWorkspace({ signOut = () => {} }: { signOut?: () => void }) {
  const { width } = useWindowDimensions(); const mobile = width < 1024;
  const [route, setRoute] = useState<Route>({ page: 'intelligence' }); const [items, setItems] = useState(fixture);
  const [attached, setAttached] = useState<string[]>([]); const [drawer, setDrawer] = useState(false); const [menu, setMenu] = useState(false); const [notes, setNotes] = useState(false); const [draft, setDraft] = useState<Draft | null>(null);
  const [priorities, setPriorities] = useState(initialPriorities); const [sources, setSources] = useState(initialSources); const [audit, setAudit] = useState(['Jordan moved “Enterprise launch” to priority #1', 'Jordan approved Cedar suggestion: “Add AI safety monitoring”', 'Jordan replaced Competitive Analysis Q3']);
  const [tasks, setTasks] = useState([{ id: 'a', title: 'Prepare executive briefing', done: false }, { id: 'b', title: 'Align external messaging', done: false }, { id: 'c', title: 'Monitor escalation triggers', done: true }, { id: 'd', title: 'Brief customer-facing teams (internal only)', done: false }]);
  const [read, setRead] = useState<string[]>(['n-3']); const unread = 2 - read.filter((id) => id !== 'n-3').length;
  const go = (next: Route) => { setRoute(next); setMenu(false); };
  const attach = (id: string) => { setAttached((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]); if (!attached.includes(id)) setDrawer(true); };
  const openDraft = (title: string, note: string, body: string, sourceTitles: string[] = []) => setDraft({ title, note, body, sources: sourceTitles });
  const complete = (objectId: string, actionId: string) => setItems((current) => current.map((item) => item.id === objectId ? { ...item, actions: item.actions.map((action) => action.id === actionId ? { ...action, status: action.status === 'Complete' ? 'Suggested' : 'Complete' } : action) } : item));
  const view = (() => {
    if (route.page === 'intelligence') return <Home items={items} open={(id) => go({ page: 'detail', id })} attach={attach} briefing={() => openDraft('Executive briefing — Regulatory inquiry', 'Regulatory inquiry gaining traction on AI data use', briefing(), ['U.S. Senate Committee', 'Wall Street Journal'])} />;
    if (route.page === 'detail') return <Detail item={getObject(items, route.id)} items={items} attached={attached} back={() => go({ page: 'intelligence' })} attach={attach} incident={() => go({ page: 'incident' })} open={(id) => go({ page: 'detail', id })} draft={openDraft} complete={complete} />;
    if (route.page === 'competitors') return <Competitors priorities={priorities} open={(id) => go({ page: 'competitor', id })} />;
    if (route.page === 'competitor') return <Competitor item={competitors.find((item) => item.id === route.id)} back={() => go({ page: 'competitors' })} open={(id) => go({ page: 'detail', id })} />;
    if (route.page === 'topics') return <Topics open={(id) => go({ page: 'topic', id })} />;
    if (route.page === 'topic') return <Topic item={topics.find((item) => item.id === route.id)} back={() => go({ page: 'topics' })} go={go} />;
    if (route.page === 'content') return <Content open={(id) => go({ page: 'detail', id })} draft={openDraft} />;
    if (route.page === 'deck') return <OnDeck open={(id) => go({ page: 'detail', id })} draft={openDraft} />;
    if (route.page === 'context') return <Context priorities={priorities} setPriorities={setPriorities} sources={sources} setSources={setSources} audit={(entry) => setAudit((current) => [entry, ...current])} cedar={() => setDrawer(true)} />;
    if (route.page === 'incident') return <Incident tasks={tasks} setTasks={setTasks} back={() => go({ page: 'detail', id: 'io-1' })} draft={openDraft} />;
    return <Settings audit={audit} />;
  })();
  return <View style={s.app}>{mobile && <View style={s.mobileBar}><GlyphButton name="menu" color={C.sandstone} hint="Open navigation" press={() => setMenu(true)} /><Text style={s.brand}>Cedar</Text><GlyphButton name="cedar" color={C.mint} hint="Open Cedar" press={() => setDrawer(true)} /></View>}<View style={s.shell}>{!mobile && <Sidebar route={route} unread={unread} go={go} notes={() => setNotes(true)} signOut={signOut} />}<View style={s.main}>{view}</View>{drawer && <CedarDrawer mobile={mobile} items={attached.map((id) => getObject(items, id)).filter(Boolean) as Intelligence[]} remove={attach} close={() => setDrawer(false)} />}</View>{menu && <Popup close={() => setMenu(false)}><Sidebar route={route} unread={unread} go={go} notes={() => { setMenu(false); setNotes(true); }} signOut={signOut} /></Popup>}{notes && <Notifications close={() => setNotes(false)} open={(next) => { setRead((all) => [...all, next]); setNotes(false); go(next === 'n-2' ? { page: 'incident' } : { page: 'detail', id: next === 'n-3' ? 'io-6' : 'io-1' }); }} />}{draft && <DraftModal draft={draft} close={() => setDraft(null)} />}</View>;
}

function T({ children, h = false }: { children: React.ReactNode; h?: boolean }) { return <Text style={h ? s.h1 : s.h2}>{children}</Text>; }
function Meta({ children }: { children: React.ReactNode }) { return <Text style={s.meta}>{children}</Text>; }
function Card({ children, style }: { children: React.ReactNode; style?: object }) { return <View style={[s.card, style]}>{children}</View>; }
function Button({ text, press, primary = false, danger = false }: { text: string; press: () => void; primary?: boolean; danger?: boolean }) { const [hovered, setHovered] = useState(false); const variant = primary ? 'primary' : danger ? 'danger' : 'secondary'; return <Pressable accessibilityRole="button" accessibilityLabel={text} onPress={press} onHoverIn={() => setHovered(true)} onHoverOut={() => setHovered(false)} style={({ pressed }) => [primary ? s.primary : s.button, variant === 'primary' ? interaction.primaryButton : variant === 'danger' ? interaction.dangerButton : interaction.secondaryButton, hovered && (variant === 'primary' ? interaction.primaryHover : variant === 'danger' ? interaction.dangerHover : interaction.buttonHover), pressed && interaction.buttonPressed]}><Text style={variant === 'primary' ? [s.primaryText, interaction.primaryButtonText] : variant === 'danger' ? interaction.dangerButtonText : [s.buttonText, interaction.secondaryButtonText]}>{text}</Text></Pressable>; }
function Glyph({ name, color = C.text, size = 18 }: { name: GlyphName; color?: string; size?: number }) { return <View style={[s.glyph, { width: size, height: size }]}>{createElement('svg', { xmlns: 'http://www.w3.org/2000/svg', width: size, height: size, viewBox: '0 0 24 24', fill: 'none', stroke: color, strokeWidth: 1.8, strokeLinecap: 'round', strokeLinejoin: 'round', 'aria-hidden': true, focusable: false }, glyph[name].map((d, index) => createElement('path', { d, key: index })))}</View>; }
function GlyphButton({ name, press, color = C.text, hint }: { name: GlyphName; press: () => void; color?: string; hint?: string }) { const [hovered, setHovered] = useState(false); const cedar = name === 'cedar'; return <View style={interaction.glyphControl}><Pressable onPress={press} accessibilityRole="button" accessibilityLabel={hint ?? name} accessibilityHint={hint} onHoverIn={() => setHovered(true)} onHoverOut={() => setHovered(false)} style={[s.icon, cedar && s.cedarOrb, hovered && (cedar ? s.cedarOrbHover : interaction.glyphButtonHover)]}><Glyph name={name} color={cedar ? C.abyss : color} size={cedar ? 15 : 18} /></Pressable>{hint && hovered && <View pointerEvents="none" style={interaction.hoverHint}><Text style={interaction.hoverHintText}>{hint}</Text></View>}</View>; }
function Badge({ kind }: { kind: Kind }) { const [color, backgroundColor] = kindColor(kind); return <View style={[s.badge, { backgroundColor }]}><Text style={[s.badgeText, { color }]}>{kind.toUpperCase()}</Text></View>; }
function LavaBackdrop() {
  const slowDrift = useSharedValue(0); const rise = useSharedValue(0); const pulse = useSharedValue(0);
  useEffect(() => {
    const ease = Easing.inOut(Easing.sin);
    slowDrift.value = withRepeat(withSequence(withTiming(1, { duration: 12600, easing: ease }), withTiming(0, { duration: 12600, easing: ease })), -1, false);
    rise.value = withRepeat(withSequence(withTiming(1, { duration: 9800, easing: ease }), withTiming(0, { duration: 9800, easing: ease })), -1, true);
    pulse.value = withRepeat(withSequence(withTiming(1, { duration: 7400, easing: ease }), withTiming(0, { duration: 7400, easing: ease })), -1, true);
    return () => { cancelAnimation(slowDrift); cancelAnimation(rise); cancelAnimation(pulse); };
  }, [pulse, rise, slowDrift]);
  const cedarBlob = useAnimatedStyle(() => ({ transform: [{ translateX: -65 + slowDrift.value * 130 }, { translateY: 28 - rise.value * 82 }, { scale: .96 + pulse.value * .12 }] }));
  const fernBlob = useAnimatedStyle(() => ({ transform: [{ translateX: 26 - slowDrift.value * 100 }, { translateY: -54 + rise.value * 118 }, { scale: 1 + pulse.value * .14 }] }));
  const mintBlob = useAnimatedStyle(() => ({ transform: [{ translateX: -20 + rise.value * 80 }, { translateY: 44 - pulse.value * 92 }, { scale: .9 + slowDrift.value * .17 }] }));
  return <View pointerEvents="none" style={s.lavaBackdrop}><View style={s.lavaAtmosphere} /><View style={s.lavaCluster}><Animated.View style={[s.lavaBlob, s.lavaCedar, cedarBlob]} /><Animated.View style={[s.lavaBlob, s.lavaFern, fernBlob]} /><Animated.View style={[s.lavaBlob, s.lavaMint, mintBlob]} /><View style={[s.lavaBlob, s.lavaLeaf]} /><View style={[s.lavaBlob, s.lavaPale]} /><View style={[s.lavaBlob, s.lavaMoss]} /></View><View style={s.lavaVignette} /></View>;
}
function WorkspaceFrame({ children }: { children: React.ReactNode }) {
  const canUseNativeGlass = isGlassEffectAPIAvailable();
  const content = <><LavaBackdrop /><View pointerEvents="none" style={s.glassSheen} /><View style={s.workspaceContent}>{children}</View></>;
  return canUseNativeGlass
    ? <GlassView glassEffectStyle="clear" tintColor="rgba(255, 251, 244, 0.26)" style={s.workspaceFrame}>{content}</GlassView>
    : <View style={[s.workspaceFrame, s.workspaceFrameFallback]}>{content}</View>;
}
function Page({ children }: { children: React.ReactNode }) { return <ScrollView style={layout.pageScroller} contentContainerStyle={layout.pageContent}><View style={[s.page, layout.page]}><WorkspaceFrame>{children}</WorkspaceFrame></View></ScrollView>; }
function Popup({ children, close }: { children: React.ReactNode; close: () => void }) { return <Modal transparent visible animationType="fade" onRequestClose={close}><Pressable style={s.backdrop} onPress={close}><Pressable onPress={(event) => event.stopPropagation()} style={s.popup}>{children}</Pressable></Pressable></Modal>; }

function Sidebar({ route, unread, go, notes, signOut }: { route: Route; unread: number; go: (route: Route) => void; notes: () => void; signOut: () => void }) { const active = route.page === 'detail' ? 'intelligence' : route.page === 'competitor' ? 'competitors' : route.page === 'topic' ? 'context' : route.page; return <View style={s.sidebar}><View style={s.workspace}><View><Text style={s.workspaceName}>cedar</Text><Text style={s.workspaceMeta}>Acme</Text></View></View>{nav.map(([icon, label, page]) => <Pressable key={page} onPress={() => go({ page })} style={[s.nav, active === page && s.navOn]}><View style={s.navIcon}><Glyph name={icon} color={active === page ? C.mint : C.sandstone} size={20} /></View><Text style={[s.navText, active === page && s.navTextOn]}>{label}</Text></Pressable>)}<View style={s.navBottom}><Pressable onPress={() => go({ page: 'settings' })} style={[s.nav, route.page === 'settings' && s.navOn]}><View style={s.navIcon}><Glyph name="settings" color={route.page === 'settings' ? C.mint : C.sandstone} size={16} /></View><Text style={[s.navText, route.page === 'settings' && s.navTextOn]}>Settings</Text></Pressable><Pressable onPress={notes} style={s.nav}><View style={s.navIcon}><Glyph name="bell" color={C.sandstone} size={16} /></View><Text style={s.navText}>Notifications</Text>{unread > 0 && <View style={s.count}><Text style={s.countText}>{unread}</Text></View>}</Pressable><Pressable onPress={signOut} style={s.nav}><View style={s.navIcon}><Glyph name="close" color={C.sandstone} size={16} /></View><Text style={s.navText}>Sign out</Text></Pressable><View style={s.user}><View style={s.avatar}><Text style={s.avatarText}>JA</Text></View><View><Text style={s.userName}>Jordan Avery</Text><Text style={s.workspaceMeta}>Communications Lead</Text></View></View></View></View>; }
function Header({ title, subtitle, back, press, right }: { title: string; subtitle?: string; back?: string; press?: () => void; right?: React.ReactNode }) { return <View style={s.header}>{back && <Pressable onPress={press}><Text style={s.back}>← {back}</Text></Pressable>}<View style={s.headerRow}><View style={s.headerCopy}><T h>{title}</T>{subtitle && <Text style={s.subtitle}>{subtitle}</Text>}</View>{right}</View></View>; }

function Home({ items, open, attach, briefing: openBriefing }: { items: Intelligence[]; open: (id: string) => void; attach: (id: string) => void; briefing: () => void }) { const topThreat = items.find((item) => item.kind === 'threat'); const topOpportunity = items.find((item) => item.kind === 'opportunity'); return <Page><Header title="Intelligence" subtitle="The signals that need your attention, with a clear read on what to do next." right={<Button text="Open today’s briefing →" press={openBriefing} />} /><View style={s.topRead}><View style={s.topReadCell}><Text style={s.eyebrow}>TOP THREAT</Text><Pressable onPress={() => topThreat && open(topThreat.id)}><Text style={s.topReadTitle}>{topThreat?.headline}</Text></Pressable><Text style={s.smallCopy}>{topThreat?.summary}</Text></View><View style={s.topReadDivider} /><View style={s.topReadCell}><Text style={s.eyebrow}>TOP OPPORTUNITY</Text><Pressable onPress={() => topOpportunity && open(topOpportunity.id)}><Text style={s.topReadTitle}>{topOpportunity?.headline}</Text></Pressable><Text style={s.smallCopy}>{topOpportunity?.summary}</Text></View></View><View style={s.homeHead}><View style={s.headlines}><Meta>WEDNESDAY, OCTOBER 21</Meta><Text style={s.sectionLead}>Latest intelligence</Text></View></View><View style={s.grid}>{items.map((item, index) => <Story key={item.id} item={item} lead={index === 0} open={open} attach={attach} />)}</View></Page>; }
function Story({ item, lead, open, attach }: { item: Intelligence; lead: boolean; open: (id: string) => void; attach: (id: string) => void }) { const compact = useWindowDimensions().width < 700; return <Card style={[s.story, lead && s.lead, compact && s.mobileStory]}><Pressable onPress={() => open(item.id)} style={s.storyInner}><Badge kind={item.kind} /><Text style={[s.storyTitle, lead && s.leadTitle]}>{item.headline}</Text><Text numberOfLines={lead ? 4 : 3} style={s.copy}>{item.summary}</Text>{lead && item.recommendation && <View style={s.recommend}><Glyph name="cedar" color={C.rust} size={14} /><Text style={s.recommendText}>Cedar recommends: {item.recommendation}</Text></View>}<View style={s.storyFoot}><Meta>Updated {item.updatedAt}</Meta><GlyphButton name="cedar" color={C.oldGrowth} hint="Ask Cedar" press={() => attach(item.id)} /></View></Pressable></Card>; }


function Tabs({ labels, selected, set }: { labels: string[]; selected: string; set: (value: string) => void }) { const companyContext = labels.includes('Strategy'); return <View style={s.tabWrap}><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={[s.tabs, interaction.tabs]}><View style={interaction.tabRow}>{labels.map((label) => <Pressable key={label} accessibilityRole="tab" accessibilityState={{ selected: selected === label }} onPress={() => set(label)} style={[s.tab, interaction.tab, selected === label && s.tabOn]}><Text style={[s.tabText, interaction.tabText, selected === label && interaction.tabTextOn]}>{label}</Text></Pressable>)}</View></ScrollView>{companyContext && <View style={s.contextThemes}><Text style={s.contextThemesLabel}>TRACKED THEMES</Text>{topics.slice(0, 4).map((topic) => <View key={topic.id} style={s.contextTheme}><Text style={s.contextThemeName}>{topic.name}</Text><Text style={s.contextThemeMeta}>{topic.state} · {topic.count} {topic.unit}</Text></View>)}</View>}</View>; }
function Detail({ item, items, attached, back, attach, incident, open, draft, complete }: { item?: Intelligence; items: Intelligence[]; attached: string[]; back: () => void; attach: (id: string) => void; incident: () => void; open: (id: string) => void; draft: (title: string, note: string, body: string, sources?: string[]) => void; complete: (item: string, action: string) => void }) {
  const [tab, setTab] = useState('Overview');
  if (!item) return <Page><Card><T h>Object not found</T></Card></Page>;
  const related = items.filter((other) => other.id !== item.id && other.topics.some((topic) => item.topics.includes(topic)));
  const inCedar = attached.includes(item.id);

  return <Page>
    <Header title={item.headline} subtitle={item.summary} back="Intelligence" press={back} right={<Button text={inCedar ? '✦ Asked Cedar' : '✦ Ask Cedar'} press={() => attach(item.id)} />} />
    <View style={s.inline}><Badge kind={item.kind} /><Meta>{item.status} · Updated {item.updatedAt}</Meta></View>
    {item.incident && <Pressable onPress={incident} style={s.incident}><Text style={s.incidentText}>Open incident workspace →</Text></Pressable>}
    <Tabs labels={['Overview', 'Updates', 'Recommended Actions', 'Related', 'History']} selected={tab} set={setTab} />
    {tab === 'Overview' && <View style={s.stack}>
      <List title="What happened" values={item.whatHappened} />
      <List title="Why this matters" values={item.whyItMatters} />
      {item.recommendation && <Recommendation text={item.recommendation} action={{ text: 'Review actions', press: () => setTab('Recommended Actions') }} secondaryAction={item.incident ? { text: 'Open incident', press: incident } : undefined} />}
      <Section title="Evidence"><View style={s.chips}>{item.signals.map((signal) => <View key={signal} style={s.chip}><Text style={s.chipText}>{signal}</Text></View>)}</View></Section>
    </View>}
    {tab === 'Updates' && <Activity />}
    {tab === 'Recommended Actions' && <Section title="Recommended actions" subtitle="Changes are recorded in the local audit trail."><Card>{item.actions.map((action, index) => <View key={action.id} style={[s.action, index < item.actions.length - 1 && s.border]}><View style={s.flex}><Text style={s.rowTitle}>{action.title}</Text><Text style={s.smallCopy}>{action.description}</Text><Meta>{action.status}</Meta></View><View style={s.actionButtons}><Button text={action.output} press={() => draft(`Draft — ${action.title}`, item.headline, `Draft for ${action.title}\n\n${item.summary}\n\nRecommended posture\n${item.recommendation ?? 'Continue monitoring.'}`, item.signals)} /><Pressable onPress={() => complete(item.id, action.id)}><Text style={s.link}>{action.status === 'Complete' ? 'Reopen' : 'Complete'}</Text></Pressable></View></View>)}</Card></Section>}
    {tab === 'Related' && <Section title="Related intelligence"><Card>{related.map((other, index) => <Pressable key={other.id} onPress={() => open(other.id)} style={[s.linkRow, index < related.length - 1 && s.border]}><Badge kind={other.kind} /><Text style={s.smallCopy}>{other.headline}</Text><Text style={s.arrow}>→</Text></Pressable>)}</Card></Section>}
    {tab === 'History' && <Section title="Historical precedent"><Card style={s.historyCard}><Text style={s.copy}>In 2023, early leadership alignment contained a similar inquiry without an external response. That outcome informs Cedar’s recommendation.</Text></Card></Section>}
  </Page>;
}
function Section({ title, subtitle, children, style }: { title: string; subtitle?: string; children: React.ReactNode; style?: object }) { return <View style={[s.section, layout.section, style]}><T>{title}</T>{subtitle && <Text style={s.subtitle}>{subtitle}</Text>}{children}</View>; }
function List({ title, values }: { title: string; values: string[] }) { return <Section title={title}><Card>{values.map((value, index) => <View key={value} style={[s.list, index < values.length - 1 && s.border]}><Text style={s.bullet}>•</Text><Text style={s.copy}>{value}</Text></View>)}</Card></Section>; }
function Recommendation({ text, action, secondaryAction }: { text: string; action?: { text: string; press: () => void }; secondaryAction?: { text: string; press: () => void } }) { return <View style={s.reco}><View style={s.recoLabel}><Glyph name="cedar" color={C.rust} size={13} /><Text style={s.eyebrow}>CEDAR RECOMMENDS</Text></View><Text style={s.recoText}>{text}</Text>{(action || secondaryAction) && <View style={interaction.recoActions}>{action && <Button primary text={action.text} press={action.press} />}{secondaryAction && <Button text={secondaryAction.text} press={secondaryAction.press} />}</View>}</View>; }
function Activity() { return <Section title="Updates"><Card>{['Cedar grouped a new source with this development.', 'Jordan reviewed the current evidence.', 'Monitoring remains active.'].map((entry, index) => <View key={entry} style={[s.list, index < 2 && s.border]}><Meta>{index ? 'Today' : 'Today, 10:46 AM'}</Meta><Text style={s.smallCopy}>{entry}</Text></View>)}</Card></Section>; }

function Competitors({ priorities, open }: { priorities: string[]; open: (id: string) => void }) { const compact = useWindowDimensions().width < 700; const [extra, setExtra] = useState(''); const [added, setAdded] = useState<string[]>([]); const positioning = [{ name: 'Acme', x: '78%', y: '28%', acme: true }, { name: 'Northstar AI', x: '68%', y: '46%' }, { name: 'Anthropic', x: '38%', y: '24%' }, { name: 'Vector Labs', x: '43%', y: '66%' }, ...added.map((name, index) => ({ name, x: `${28 + index * 12}%`, y: `${58 - index * 8}%` }))]; const add = () => { const name = extra.trim(); if (name && !added.includes(name)) setAdded((all) => [...all, name]); setExtra(''); }; return <Page><Header title="Positioning" subtitle="A live competitive read through the two strategic priorities currently shaping Acme’s decisions." right={<Button text="Refresh from sources" press={() => {}} />} /><Card style={s.matrixCard}><View style={s.matrixHead}><View><Text style={s.eyebrow}>STRATEGIC POSITIONING</Text><Text style={s.matrixTitle}>Where the market sits against what matters now</Text></View><Meta>Based on company context + tracked sources</Meta></View><View style={s.matrix}><Text style={s.matrixYAxis}>↑ {priorities[0] ?? 'Enterprise launch'}</Text><Text style={s.matrixAxisTop}>Higher readiness</Text><Text style={s.matrixAxisBottom}>Lower readiness</Text><View style={s.matrixV} /><View style={s.matrixH} />{positioning.map((item) => <View key={item.name} style={[s.matrixPoint, item.acme && s.matrixPointAcme, { left: item.x as never, top: item.y as never }]}><View style={s.matrixDot}><Text style={s.matrixDotText}>{item.acme ? 'A' : item.name.slice(0, 1)}</Text></View><Text style={[s.matrixLabel, item.acme && s.matrixLabelAcme]}>{item.name}</Text></View>)}<Text style={s.matrixXAxis}>← Less aligned to {priorities[1] ?? 'grow enterprise business'} · More aligned →</Text></View><View style={s.matrixInput}><TextInput value={extra} onChangeText={setExtra} onSubmitEditing={add} placeholder="Add a competitor to map" placeholderTextColor={C.faint} style={s.matrixTextInput} /><Button text="Add to matrix" press={add} /></View></Card><Section title="Tracked players" subtitle="Open a player for source-backed narrative changes and recommendations."><View style={[s.twoGrid, layout.twoGrid]}>{competitors.map((item) => <Pressable key={item.id} onPress={() => open(item.id)} style={[layout.competitor, compact && s.mobileCompetitor]}><Card style={[s.competitor, interaction.competitorCard, compact && s.mobileCompetitor]}><View style={s.between}><Text style={s.cardTitle}>{item.name}</Text><Meta>{item.tier}</Meta></View><Text style={s.smallCopy}>{item.count} new signals</Text>{item.highlights.map((highlight) => <Text key={highlight} style={s.smallCopy}>• {highlight}</Text>)}</Card></Pressable>)}</View></Section></Page>; }
function Competitor({ item, back, open }: { item?: (typeof competitors)[number]; back: () => void; open: (id: string) => void }) { if (!item) return <Page><Card><T h>Competitor not found</T></Card></Page>; return <Page><Header title={item.name} subtitle={`${item.tier} competitor`} back="Positioning" press={back} /><List title="What changed" values={[item.changed]} /><List title="Current positioning" values={[item.positioning]} /><List title="Narrative overlap with Acme" values={[item.overlap]} /><Recommendation text={item.recommendation} action={{ text: 'Review related intelligence', press: () => open(item.intelligence[0]) }} /><Section title="Related intelligence"><Card>{item.intelligence.map((id, index) => { const related = getObject(fixture, id); return related && <Pressable key={id} onPress={() => open(id)} style={[s.linkRow, index < item.intelligence.length - 1 && s.border]}><Badge kind={related.kind} /><Text style={s.smallCopy}>{related.headline}</Text><Text style={s.arrow}>→</Text></Pressable>; })}</Card></Section></Page>; }
function Topics({ open }: { open: (id: string) => void }) { return <Page><Header title="Topics" subtitle="Strategic themes Cedar watches — persistent context, not keyword alerts." /><Card>{topics.map((item, index) => <Pressable key={item.id} onPress={() => open(item.id)} style={[s.topic, index < topics.length - 1 && s.border]}><Text style={s.topicName}>{item.name}</Text><Text style={s.state}>{item.state}</Text><Text style={s.smallCopy}>{item.count} {item.unit}</Text><Text style={s.arrow}>→</Text></Pressable>)}</Card></Page>; }
function Topic({ item, back, go }: { item?: (typeof topics)[number]; back: () => void; go: (route: Route) => void }) { if (!item) return <Page><Card><T h>Topic not found</T></Card></Page>; return <Page><Header title={item.name} subtitle={`${item.state} · ${item.count} ${item.unit} tracked`} back="Topics" press={back} /><Recommendation text={item.synthesis} action={{ text: 'Review related intelligence', press: () => go({ page: 'detail', id: item.intelligence[0] }) }} /><Section title="Why Cedar tracks this"><Text style={s.copy}>{item.why}</Text></Section><Section title="Related intelligence"><Card>{item.intelligence.map((id, index) => { const related = getObject(fixture, id); return related && <Pressable key={id} onPress={() => go({ page: 'detail', id })} style={[s.linkRow, index < item.intelligence.length - 1 && s.border]}><Badge kind={related.kind} /><Text style={s.smallCopy}>{related.headline}</Text><Text style={s.arrow}>→</Text></Pressable>; })}</Card></Section><Section title="Competitors"><Card>{item.competitors.map((id, index) => { const related = competitors.find((candidate) => candidate.id === id); return related && <Pressable key={id} onPress={() => go({ page: 'competitor', id })} style={[s.linkRow, index < item.competitors.length - 1 && s.border]}><Text style={s.smallCopy}>{related.name}</Text><Text style={s.arrow}>→</Text></Pressable>; })}</Card></Section></Page>; }

function Content({ open, draft }: { open: (id: string) => void; draft: (title: string, note: string, body: string, sources?: string[]) => void }) { const [selected, setSelected] = useState<Opportunity>(opportunities[0]); const [assignees, setAssignees] = useState<Record<string, { initials: string; name: string }>>({ 'co-1': { initials: 'MC', name: 'Maya Chen' }, 'co-2': { initials: 'JA', name: 'Jordan Avery' }, 'co-4': { initials: 'LB', name: 'Leo Brooks' } }); const compact = useWindowDimensions().width < 700; const assign = () => setAssignees((all) => ({ ...all, [selected.id]: all[selected.id]?.initials === 'RP' ? { initials: 'JA', name: 'Jordan Avery' } : { initials: 'RP', name: 'Rina Patel' } })); const person = assignees[selected.id]; return <Page><Header title="Content Advisor" subtitle="Drafts born from live flags and opportunities, ready for a teammate to own." /><View style={[s.content, layout.content, compact && s.contentMobile]}><View style={[s.contentList, compact && s.contentListMobile]}>{opportunities.filter((item) => item.kind === 'flag' || item.kind === 'opportunity').map((item) => { const owner = assignees[item.id]; return <Pressable key={item.id} onPress={() => setSelected(item)} style={[s.contentItem, selected.id === item.id && s.contentOn]}><Badge kind={item.kind} /><Text style={s.rowTitle}>{item.category}</Text><Text style={s.smallCopy}>{item.title}</Text><Meta>{item.channel} · {item.timing}</Meta>{owner && <View style={s.assignee}><View style={s.assigneeAvatar}><Text style={s.assigneeAvatarText}>{owner.initials}</Text></View><Text style={s.assigneeText}>{owner.name}</Text></View>}</Pressable>; })}</View><Card style={s.contentDetail}><View style={s.between}><View><Text style={s.eyebrow}>{selected.kind === 'flag' ? 'FLAG RESPONSE' : 'OPPORTUNITY DRAFT'}</Text><Meta>{selected.category}</Meta></View><Badge kind={selected.kind} /></View><T h>{selected.title}</T><Section title="Why now"><Text style={s.copy}>{selected.why}</Text></Section><Section title="Evidence"><View style={s.chips}>{selected.evidence.map((id) => { const evidence = getObject(fixture, id); return evidence && <Pressable key={id} onPress={() => open(id)} style={s.chip}><Text style={s.chipText}>{evidence.headline}</Text></Pressable>; })}</View></Section><Meta>CHANNEL · {selected.channel}{`\n`}ACCOUNT · {selected.account}{`\n`}TIMING · {selected.timing}</Meta><View style={s.draftAssignment}><View>{person ? <View style={s.assignee}><View style={s.assigneeAvatar}><Text style={s.assigneeAvatarText}>{person.initials}</Text></View><View><Text style={s.assigneeText}>Assigned to {person.name}</Text><Meta>Owner of this draft</Meta></View></View> : <Meta>Unassigned draft</Meta>}</View><Button text={person ? 'Reassign' : 'Assign teammate'} press={assign} /></View><Button primary text="Open draft" press={() => draft(`Draft — ${selected.title}`, selected.why, selected.draft, selected.evidence.map((id) => getObject(fixture, id)?.headline ?? id))} /></Card></View></Page>; }

function OnDeck({ open, draft }: { open: (id: string) => void; draft: (title: string, note: string, body: string, sources?: string[]) => void }) { const [done, setDone] = useState<string[]>([]); const tasks = [{ id: 'd1', title: 'Approve regulatory holding statement', detail: 'Owner: you · Before 2:00 PM', insight: 'io-1' }, { id: 'd2', title: 'Review CEO POV on operational proof', detail: 'Owner: you · Today', insight: 'io-10' }, { id: 'd3', title: 'Confirm Northwind story permissions', detail: 'Owner: you · Tomorrow', insight: 'io-14' }]; return <Page><Header title="On Deck" subtitle="The shared rhythm around live intelligence — decisions, moments and response." /><View style={s.deckGrid}><View style={s.deckWide}><Section title="Assigned to you" subtitle="The next decisions that keep momentum moving."><Card>{tasks.map((task, index) => <Pressable key={task.id} onPress={() => setDone((all) => all.includes(task.id) ? all.filter((id) => id !== task.id) : [...all, task.id])} style={[s.deckTask, index < tasks.length - 1 && s.border]}><View style={[s.taskCheck, done.includes(task.id) && s.taskCheckDone]}><Text style={s.taskCheckText}>{done.includes(task.id) ? '✓' : ''}</Text></View><View style={s.flex}><Text style={[s.rowTitle, done.includes(task.id) && s.strike]}>{task.title}</Text><Meta>{task.detail}</Meta></View><Pressable onPress={() => open(task.insight)}><Text style={s.link}>Insight →</Text></Pressable></Pressable>)}</Card></Section><Section title="Team priorities"><Card><View style={s.teamPriority}><Text style={s.priorityNumber}>01</Text><View><Text style={s.rowTitle}>Enterprise launch narrative</Text><Text style={s.smallCopy}>Executive claims, launch proof points and response posture must align before dry run.</Text></View></View><View style={[s.teamPriority, s.border]}><Text style={s.priorityNumber}>02</Text><View><Text style={s.rowTitle}>Turn customer proof into market authority</Text><Text style={s.smallCopy}>Secure Northwind approval and package the audit-trail story for earned and owned channels.</Text></View></View></Card></Section></View><View style={s.deckRail}><Section title="Team comms"><Card><View style={s.commsNote}><View style={s.assignee}><View style={s.assigneeAvatar}><Text style={s.assigneeAvatarText}>MC</Text></View><Text style={s.assigneeText}>Maya Chen · 10:22 AM</Text></View><Text style={s.smallCopy}>“I’ll take the CEO POV if Legal clears the operational proof language.”</Text><Pressable onPress={() => draft('CEO POV — Responsible AI needs operational proof', 'Opening created by live governance conversation', opportunities[0].draft, ['Northwind policy note'])}><Text style={s.link}>Open response draft →</Text></Pressable></View><View style={[s.commsNote, s.border]}><View style={s.assignee}><View style={s.assigneeAvatar}><Text style={s.assigneeAvatarText}>RP</Text></View><Text style={s.assigneeText}>Rina Patel · 9:48 AM</Text></View><Text style={s.smallCopy}>“CBC’s embargo lifts Thursday. We need a single source of truth by tomorrow afternoon.”</Text></View></Card></Section><Section title="Coming up"><Card><View style={s.calendarRow}><Glyph name="calendar" color={C.rust} size={17} /><View><Text style={s.rowTitle}>Today · 2:00 PM</Text><Text style={s.smallCopy}>Bloomberg holding statement review</Text></View></View><View style={[s.calendarRow, s.border]}><Glyph name="calendar" color={C.rust} size={17} /><View><Text style={s.rowTitle}>Tomorrow · 11:00 AM</Text><Text style={s.smallCopy}>CBC exclusive embargo briefing</Text></View></View><View style={[s.calendarRow, s.border]}><Glyph name="calendar" color={C.rust} size={17} /><View><Text style={s.rowTitle}>Thursday · 9:00 AM</Text><Text style={s.smallCopy}>CBC exclusive released · response monitoring</Text></View></View></Card></Section></View></View></Page>; }

function Context({ priorities, setPriorities, sources, setSources, audit, cedar }: { priorities: string[]; setPriorities: (values: string[]) => void; sources: typeof initialSources; setSources: (values: typeof initialSources) => void; audit: (entry: string) => void; cedar: () => void }) { const [tab, setTab] = useState('Overview'); const sections = ['Overview', 'Strategy', 'Positioning', 'Audiences', 'Competitors', 'Risks & Issues', 'Voice & Content', 'Sources']; return <Page><Header title="Company Context" subtitle="What Cedar understands about Acme — with provenance on every derived item." /><Tabs labels={sections} selected={tab} set={setTab} />{tab === 'Overview' && <View style={s.stack}><Section title="Strategic priorities" subtitle="Drag priorities to re-rank. Changes are logged."><PriorityList priorities={priorities} setPriorities={setPriorities} audit={audit} /></Section><Section title="Context review" subtitle="Cedar proposes; you decide. Nothing becomes company truth silently."><Card><View style={s.review}><Text style={s.eyebrow}>CEDAR FOUND SOMETHING NEW</Text><Text style={s.rowTitle}>Suggested priority: Enterprise differentiation</Text><Text style={s.smallCopy}>Why: Repeated across the strategy deck and launch plan.</Text><View style={s.inline}><Button text="Confirm" press={() => audit('Jordan approved Cedar suggestion: “Enterprise differentiation”')} /><Button text="Ask Cedar" press={cedar} /></View></View></Card></Section><List title="Company snapshot" values={['Acme · Enterprise AI infrastructure · Series B', 'San Francisco · Remote-first · ~180 employees', 'Make enterprise AI deployment secure, governable, and practical.']} /></View>}{tab === 'Sources' && <Section title="Sources" subtitle="Replacing a source triggers re-evaluation of derived intelligence."><Button text="Add document" press={() => { setSources([...sources, { id: `local-${sources.length}`, name: 'New local context.pdf', type: 'Upload', status: 'Processing', facts: 0 }]); audit('Jordan added a local context document'); }} /><Card>{sources.map((source, index) => <View key={source.id} style={[s.source, index < sources.length - 1 && s.border]}><View style={s.flex}><Text style={s.rowTitle}>{source.name}</Text><Meta>{source.type} · {source.status} · {source.facts} derived facts</Meta></View><Button text="Replace" press={() => { setSources(sources.map((item) => item.id === source.id ? { ...item, status: 'Processing' } : item)); audit(`Jordan replaced ${source.name}`); }} /><Button danger text="Remove" press={() => { setSources(sources.filter((item) => item.id !== source.id)); audit(`Jordan removed ${source.name}`); }} /></View>)}</Card></Section>}{tab === 'Strategy' && <List title="Company goals" values={['Launch enterprise tier by November 20', 'Raise Series C in H1 2027', 'Win three marquee financial-services logos by Q4', 'Own governed AI deployment as a category position']} />}{tab === 'Positioning' && <List title="Positioning" values={['Enterprise AI deployment platform for regulated industries.', 'Acme makes enterprise AI deployment secure, governable, and practical.', 'Audit trail ships on by default — not an add-on tier.']} />}{tab === 'Audiences' && <List title="Audiences" values={['Enterprise buyers — proof over promises.', 'Investors — governance as durable advantage.', 'Existing customers — factual reassurance before they ask.', 'Journalists — one consistent answer.']} />}{tab === 'Competitors' && <List title="Tracked competitive set" values={competitors.map((item) => `${item.name} · ${item.tier}`)} />}{tab === 'Risks & Issues' && <List title="Escalation playbook" values={['Funding leak → founder + legal escalation', 'Major customer dispute → CEO + customer owner', 'Regulatory inquiry → comms + legal + policy review within four hours']} />}{tab === 'Voice & Content' && <List title="Voice profiles" values={['Brand voice — clear over clever; proof before promises.', 'CEO voice — technically literate, operational examples.', 'Avoid hype, generic futurism, and competitor dunking.']} />}</Page>; }
function PriorityList({ priorities, setPriorities, audit }: { priorities: string[]; setPriorities: (values: string[]) => void; audit: (entry: string) => void }) { const [dragging, setDragging] = useState<string | null>(null); const reorder = (from: string, to: string) => { if (from === to) { setDragging(null); return; } const next = [...priorities], fromIndex = next.indexOf(from), toIndex = next.indexOf(to); if (fromIndex < 0 || toIndex < 0) return; next.splice(fromIndex, 1); next.splice(toIndex, 0, from); setPriorities(next); audit(`Jordan re-ranked priority “${from}”`); setDragging(null); }; return <Card>{priorities.map((priority, index) => createElement('div', { key: priority, draggable: true, role: 'listitem', tabIndex: 0, 'aria-label': `Drag ${priority} to reorder`, onDragStart: () => setDragging(priority), onDragEnd: () => setDragging(null), onDragOver: (event: { preventDefault: () => void }) => event.preventDefault(), onDrop: () => { if (dragging) reorder(dragging, priority); }, style: { cursor: 'grab', userSelect: 'none' } }, <View style={[s.priority, dragging === priority && interaction.priorityDragging, index < priorities.length - 1 && s.border]}><View style={interaction.dragHandle}><Glyph name="drag" color={C.faint} size={16} /></View><Text style={s.number}>{index + 1}</Text><Text style={s.copy}>{priority}</Text></View>))}</Card>; }
function Incident({ tasks, setTasks, back, draft }: { tasks: { id: string; title: string; done: boolean }[]; setTasks: (items: { id: string; title: string; done: boolean }[]) => void; back: () => void; draft: (title: string, note: string, body: string, sources?: string[]) => void }) { const [tab, setTab] = useState('Workspace'); return <Page><Header title="Regulatory inquiry on AI data use" subtitle="Incident workspace · regulatory inquiry gaining traction" back="Intelligence" press={back} /><Tabs labels={['Workspace', 'Updates', 'Response plan', 'Drafts', 'Stakeholders', 'Timeline']} selected={tab} set={setTab} />{tab === 'Workspace' && <View style={[s.incidentGrid, layout.incidentGrid]}><Section style={layout.incidentPlan} title="Action plan"><Card>{tasks.map((task, index) => <Pressable key={task.id} onPress={() => setTasks(tasks.map((item) => item.id === task.id ? { ...item, done: !item.done } : item))} style={[s.task, index < tasks.length - 1 && s.border]}><Text style={[s.check, task.done && { color: C.op }]}>{task.done ? '✓' : '□'}</Text><Text style={[s.copy, task.done && s.strike]}>{task.title}</Text></Pressable>)}</Card></Section><View style={s.aside}><T>Current owners</T><Text style={s.smallCopy}>• Jordan · Communications{`\n`}• Taylor · Legal{`\n`}• Rina · Policy{`\n`}• Maya · Executive owner</Text><T>Escalation triggers</T><Text style={s.smallCopy}>• Inquiry names Acme directly{`\n`}• Hearing date is scheduled{`\n`}• Coverage mentions Acme by name{`\n`}• Customer renewal cites the inquiry</Text></View></View>}{tab === 'Updates' && <Activity />}{tab === 'Response plan' && <Recommendation text="Brief leadership now and prepare — but do not publish — external language." />}{tab === 'Drafts' && <Section title="Prepared drafts"><Card><View style={s.action}><View><Text style={s.rowTitle}>Executive briefing</Text><Meta>In progress</Meta></View><Button text="Open draft" press={() => draft('Executive briefing — Regulatory inquiry', 'Regulatory inquiry', briefing())} /></View></Card></Section>}{tab === 'Stakeholders' && <List title="Stakeholders" values={['Jordan Avery · Communications', 'Taylor Brooks · Legal', 'Rina Patel · Policy', 'Maya Chen · Executive owner']} />}{tab === 'Timeline' && <Activity />}</Page>; }
function Settings({ audit }: { audit: string[] }) { const [hours, setHours] = useState(['9:00 AM', '6:00 PM']); const [routes, setRoutes] = useState([true, true, true, true]); return <Page><Header title="Settings" /><Section title="Notification routing" subtitle="Delivery follows severity × working hours. No separate notifications page."><Card>{[['Threat', 'Working hours', 'Slack + Email'], ['Threat', 'After hours', 'Phone + Slack'], ['Flag', 'Any', 'Daily digest'], ['Opportunity', 'Any', 'Morning / afternoon digest']].map(([kind, time, delivery], index) => <View key={kind + time} style={[s.setting, index < 3 && s.border]}><Text style={s.settingName}>{kind}</Text><Text style={s.smallCopy}>{time}</Text><Text style={s.smallCopy}>{delivery}</Text><Pressable onPress={() => setRoutes(routes.map((value, position) => position === index ? !value : value))} style={[s.toggle, routes[index] && s.toggleOn]}><View style={[s.knob, routes[index] && s.knobOn]} /></Pressable></View>)}</Card></Section><Section title="Working hours" subtitle="Drives the after-hours escalation path for threats."><View style={s.inline}><Text style={s.smallCopy}>From</Text><TextInput value={hours[0]} onChangeText={(value) => setHours([value, hours[1]])} style={s.input} /><Text style={s.smallCopy}>To</Text><TextInput value={hours[1]} onChangeText={(value) => setHours([hours[0], value])} style={s.input} /></View></Section><Section title="Connected services"><Card>{['Slack · Connected', 'Email · Connected', 'Phone · On-call configured', 'Teams · Not connected'].map((service, index) => <View key={service} style={[s.setting, index < 3 && s.border]}><Text style={s.settingName}>{service.split(' · ')[0]}</Text><Text style={s.smallCopy}>{service.split(' · ')[1]}</Text><Button text={service.includes('Not') ? 'Connect' : 'Manage'} press={() => {}} /></View>)}</Card></Section><Section title="Context audit trail" subtitle="Who changed what Cedar believes, and when."><Card>{audit.map((entry, index) => <View key={`${entry}${index}`} style={[s.list, index < audit.length - 1 && s.border]}><Meta>{index ? 'Earlier' : 'Now'}</Meta><Text style={s.smallCopy}>{entry}</Text></View>)}</Card></Section></Page>; }

function Notifications({ close, open }: { close: () => void; open: (id: string) => void }) { const notes = [['n-1', 'Regulatory inquiry upgraded to Material', 'WSJ confirms a possible hearing next month. Cedar recommends leadership briefing today.', '3m ago'], ['n-2', 'Incident workspace opened: Regulatory inquiry', 'After-hours escalation rule fired. Action plan is ready for morning review.', 'Last night'], ['n-3', 'AI-search visibility decline flagged', 'Acme omitted from 6 of 10 high-intent enterprise prompts.', '7:01 AM']]; return <Popup close={close}><View style={s.notes}><View style={s.noteHead}><T>Notifications</T><GlyphButton name="close" press={close} /></View>{notes.map(([id, title, body, time]) => <Pressable key={id} onPress={() => open(id)} style={s.note}><View style={[s.dot, id !== 'n-3' && { backgroundColor: C.threat }]} /><View style={s.flex}><Text style={s.rowTitle}>{title}</Text><Text style={s.smallCopy}>{body}</Text><Meta>{time}</Meta></View></Pressable>)}</View></Popup>; }
function CedarDrawer({ mobile, items, remove, close }: { mobile: boolean; items: Intelligence[]; remove: (id: string) => void; close: () => void }) {
  const [question, setQuestion] = useState('');
  const [messages, setMessages] = useState<{ user: boolean; text: string }[]>([]);
  const [loading, setLoading] = useState(false);
  const send = () => {
    if (!question.trim() || loading) return;
    const value = question;
    setQuestion('');
    setMessages((all) => [...all, { user: true, text: value }]);
    setLoading(true);
    setTimeout(() => {
      setMessages((all) => [...all, { user: false, text: cedarAnswer(items) }]);
      setLoading(false);
    }, 500);
  };
  const body = <View style={[s.drawer, mobile && s.drawerMobile]}>
    <View style={s.drawerHead}>
      <View><View style={s.drawerTitleRow}><Glyph name="cedar" color={C.oldGrowth} size={17} /><Text style={s.drawerTitle}>Cedar, your content advisor</Text></View><Meta>{items.length ? `Reasoning across ${items.length} selected development${items.length === 1 ? '' : 's'}` : 'Ask Cedar about any development to begin'}</Meta></View>
      <GlyphButton name="close" press={close} />
    </View>
    <ScrollView style={s.drawerScroll}>
      <Text style={s.eyebrow}>IN THIS CONVERSATION</Text>
      {items.length ? <View style={s.attached}>{items.map((item) => <View key={item.id} style={s.attachChip}><Text numberOfLines={1} style={s.chipText}>{item.headline}</Text><Pressable onPress={() => remove(item.id)} accessibilityLabel={`Remove ${item.headline} from Cedar`}><Text style={s.link}>×</Text></Pressable></View>)}</View> : <Text style={s.smallCopy}>Nothing here yet. Choose Ask Cedar on any development to bring it into this conversation.</Text>}
      {messages.map((message, index) => <View key={`${message.text}${index}`} style={[s.message, message.user ? s.userMessage : s.cedarMessage]}><Text style={message.user ? s.userMessageText : s.cedarMessageText}>{message.text}</Text></View>)}
      {loading && <Meta>Cedar is reasoning across your selected developments…</Meta>}
    </ScrollView>
    <View style={s.composer}><TextInput value={question} onChangeText={setQuestion} onSubmitEditing={send} placeholder="Ask Cedar about these developments…" placeholderTextColor={C.faint} style={s.composerInput} /><Button primary text="Ask Cedar" press={send} /></View>
  </View>;
  return mobile ? <Popup close={close}>{body}</Popup> : body;
}
function DraftModal({ draft, close }: { draft: Draft; close: () => void }) { const [body, setBody] = useState(draft.body); return <Popup close={close}><View style={s.draft}><View style={s.draftContext}><Text style={s.eyebrow}>CONTEXT</Text><T>Why now</T><Text style={s.smallCopy}>{draft.note}</Text><T>Sources</T>{draft.sources.map((source) => <Text key={source} style={s.smallCopy}>• {source}</Text>)}<T>Voice rules</T><Text style={s.smallCopy}>✓ Clear over clever{`\n`}✓ Proof before promises{`\n`}✓ Plain language</Text></View><View style={s.draftMain}><View style={s.noteHead}><View><Text style={s.eyebrow}>DRAFT</Text><T>{draft.title}</T></View><GlyphButton name="close" press={close} /></View><TextInput multiline value={body} onChangeText={setBody} textAlignVertical="top" style={s.editor} /><View style={s.draftFoot}><Meta>Draft — internal only. External publication always requires human approval.</Meta><Button primary text="Save draft" press={close} /></View></View></View></Popup>; }
function cedarAnswer(items: Intelligence[]) { if (!items.length) return 'Choose Ask Cedar on a development and I’ll reason across the signals, company context, and historical precedent you select.'; return `Here’s how I read the ${items.length} selected development${items.length === 1 ? '' : 's'} together:\n\n${items.map((item) => `• ${item.headline} — ${item.kind}, ${item.status.toLowerCase()}. ${item.summary}`).join('\n')}\n\nRecommendation: brief leadership now and refresh launch differentiation around operational evidence. Do not publish externally until the inquiry status changes.`; }
function briefing() { return 'Executive briefing — Regulatory inquiry\n\nWhat happened\nSenators requested additional information on AI data practices and coverage points to a possible hearing next month.\n\nExposure\nThe enterprise launch is four weeks away; data governance is central to Acme’s positioning.\n\nRecommended posture\nBrief leadership now. Prepare — but do not publish — external language.'; }

